#!/usr/bin/env node
// Consistency test of the hot-fix bundle ../ops/hotfix-2026-10-06-openrouter-params/ (OpenRouter image parameters, one Build OpenRouter Image
// node update per workflow). The bundle is generated by make-hotfix.js from the BEFORE baselines (../ops/before/) and the main sources, so this
// test first runs node make-hotfix.js --check (every bundle file = what the generator writes, exit 0) and then asserts the composition itself:
// the hotfix SDK files equal the BEFORE baselines in every node, setting and connection except the jsCode of Build OpenRouter Image; the WF-2
// hotfix jsCode = the main source node (../wf2-generate.sdk.js); the WF-3 hotfix jsCode = the BEFORE node minus its last line
// (return { json: { body } };) + the pruning tail of the main WF-3 node (../wf3-edit.sdk.js) - region-free, because the live WF-3 graph has no
// region lane; the pruning tail (from the top-level comment that starts with // OpenRouter validates to the final return) is byte-identical in
// WF-2 main, WF-3 main and both hotfix nodes; each wfN.ops.json equals a fresh diff-ops.js run and holds exactly one updateNodeParameters op
// for Build OpenRouter Image (jsCode only, replace true, jsCode = the hotfix node); the paste files equal the node jsCode byte for byte with
// NO trailing newline (AFTER = hotfix node, .before = BEFORE node); ../ops/wf2.ops.json / wf3.ops.json (Step C) carry the Build OpenRouter
// Image node of the MAIN sources (WF-2 = the hotfix node itself; WF-3 = the main node, same tail, plus the region branch); the README names
// both live ids, every file and make-hotfix.js; the Code-node rules hold (<= 20 lines, quote-free top-level comments, colon-free thrown
// messages, no backslash); and the hotfix codes run under the LIVE graph shapes: the user's failing case (Sunburst, aspect 4:5, resolution 2K,
// output_format png, 3 refs) gives body model, prompt, n, aspect_ratio 3:4, background, input_references with dropped [resolution,
// output_format] and mapped [aspect_ratio 4:5 to 3:4] (static table and live fixture), edit_text on gemini-2.5-flash-image prunes to
// model, prompt, n, aspect_ratio, input_references and keeps 4:5, and the WF-3 hotfix takes the edit path even when pe.region is PRESENT
// (prompt-engine v8.1 deployed before Step C) while the main node would take the region branch; for a really 4:5 parent the hotfix stays inert
// where the main node throws the fit shape message before the paid call (no fit in the BEFORE head). Usage: node test-openrouter-hotfix.js
const fs = require('fs');
const path = require('path');
const { execFileSync, spawnSync } = require('child_process');
const { parseWorkflowCodeToBuilder } = require('@n8n/workflow-sdk');
const caps = require('./openrouter-caps.js');

const H = path.resolve(__dirname, '..', 'ops', 'hotfix-2026-10-06-openrouter-params');
const parse = (file) => parseWorkflowCodeToBuilder(fs.readFileSync(file, 'utf8').split('\n').filter((l) => !/^\s*import\s.*from\s+['"]@n8n\/workflow-sdk['"]/.test(l)).join('\n')).toJSON();
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let failures = 0;
const check = (cond, msg) => { if (cond) console.log('ok   ' + msg); else { failures++; console.log('FAIL ' + msg); } };
const NODE = 'Build OpenRouter Image';
const SETTINGS = ['onError', 'retryOnFail', 'maxTries', 'waitBetweenTries', 'alwaysOutputData', 'executeOnce'];
const stripSticky = (wf) => wf.nodes.filter((n) => n.type !== 'n8n-nodes-base.stickyNote');
// the SDK generates id / webhookId on every parse, so they are not compared
const minusCode = (n) => ({ ...n, id: undefined, webhookId: undefined, parameters: n.name === NODE ? { ...n.parameters, jsCode: '<jsCode>' } : n.parameters });
const codeOf = (wf) => { const n = wf.nodes.find((x) => x.name === NODE); if (!n) throw new Error('node not found'); return String(n.parameters.jsCode); };
const rulesOk = (code) => { const lines = code.split('\n'); return lines.length <= 20 && lines.filter((l) => /^\s*\/\//.test(l)).every((l) => !/['"`]/.test(l)) && (code.match(/throw new Error\(([^)]*)\)/g) || []).every((t) => !/:/.test(t)) && !/\\/.test(code); };

const SETS = [
  { wf: 'wf2', id: 'KVLDYPaWZZZtOoir', before: path.resolve(__dirname, '..', 'ops', 'before', 'wf2-generate.sdk.js'), hotfix: path.join(H, 'wf2-generate.hotfix.sdk.js'), main: path.resolve(__dirname, '..', 'wf2-generate.sdk.js'), ops: path.join(H, 'wf2.ops.json'), stepC: path.resolve(__dirname, '..', 'ops', 'wf2.ops.json'), paste: path.join(H, 'wf2-build-openrouter-image.js'), pasteBefore: path.join(H, 'wf2-build-openrouter-image.before.js') },
  { wf: 'wf3', id: 'V83NWHjzDdyiqtNP', before: path.resolve(__dirname, '..', 'ops', 'before', 'wf3-edit.sdk.js'), hotfix: path.join(H, 'wf3-edit.hotfix.sdk.js'), main: path.resolve(__dirname, '..', 'wf3-edit.sdk.js'), ops: path.join(H, 'wf3.ops.json'), stepC: path.resolve(__dirname, '..', 'ops', 'wf3.ops.json'), paste: path.join(H, 'wf3-build-openrouter-image.js'), pasteBefore: path.join(H, 'wf3-build-openrouter-image.before.js') }
];
// 1. the generator agrees with every file on disk
const gen = spawnSync('node', [path.join(__dirname, 'make-hotfix.js'), '--check'], { encoding: 'utf8' });
check(gen.status === 0, 'node make-hotfix.js --check exits 0 (every bundle file = what the generator writes)' + (gen.status === 0 ? '' : '\n' + (gen.stdout || '') + (gen.stderr || '')));
const readme = fs.existsSync(path.join(H, 'README.md')) ? fs.readFileSync(path.join(H, 'README.md'), 'utf8') : '';
check(readme.length > 0 && readme.includes('make-hotfix.js'), 'README.md exists in the bundle and names make-hotfix.js');
const codes = {};
for (const s of SETS) {
  const before = parse(s.before), hot = parse(s.hotfix), main = parse(s.main);
  codes[s.wf] = { before: codeOf(before), hot: codeOf(hot), main: codeOf(main) };
  const b = stripSticky(before), h = stripSticky(hot);
  check(same(b.map(minusCode), h.map(minusCode)) && same(before.connections, hot.connections) && same(b.map((n) => SETTINGS.map((k) => n[k])), h.map((n) => SETTINGS.map((k) => n[k]))), s.wf + ' hotfix SDK file = the BEFORE baseline in every node (name, type, position, parameters), setting and connection except the jsCode of ' + NODE);
  const stickyB = before.nodes.find((n) => n.type === 'n8n-nodes-base.stickyNote'), stickyH = hot.nodes.find((n) => n.type === 'n8n-nodes-base.stickyNote');
  check(stickyB && stickyH && same(stickyB.parameters, stickyH.parameters), s.wf + ' hotfix SDK file: the sticky note is untouched (Step C updates it)');
  const { before: bc, hot: hc, main: mc } = codes[s.wf];
  if (s.wf === 'wf2') check(hc === mc && hc !== bc, 'wf2 hotfix ' + NODE + ' jsCode = the main source node exactly (and differs from BEFORE)');
  else {
    const head = bc.split('\n');
    check(head[head.length - 1] === 'return { json: { body } };' && hc === head.slice(0, -1).join('\n') + '\n' + caps.pruningTailOf(mc) && hc !== mc && !/region|const fit = /.test(hc), 'wf3 hotfix ' + NODE + ' jsCode = the BEFORE node minus its last line (return { json: { body } };) + newline + the pruning tail of the main WF-3 node exactly - no region branch, no fit (the live graph has no region lane)');
  }
  check(caps.pruningTailOf(hc) === caps.pruningTailOf(mc), s.wf + ' hotfix and main ' + NODE + ': the same pruning tail byte for byte');
  const ops = JSON.parse(fs.readFileSync(s.ops, 'utf8'));
  const fresh = JSON.parse(execFileSync('node', [path.join(__dirname, 'diff-ops.js'), s.before, s.hotfix], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }));
  check(same(ops, fresh), s.wf + '.ops.json = node diff-ops.js <before> <hotfix> (fresh run)');
  check(ops.length === 1 && ops[0].type === 'updateNodeParameters' && ops[0].nodeName === NODE && ops[0].replace === true && same(Object.keys(ops[0].parameters), ['jsCode']) && ops[0].parameters.jsCode === hc, s.wf + '.ops.json: exactly one op, updateNodeParameters ' + NODE + ' {jsCode} replace true, jsCode = the hotfix node');
  const paste = fs.readFileSync(s.paste, 'utf8'), pasteBefore = fs.readFileSync(s.pasteBefore, 'utf8');
  check(paste === hc && !paste.endsWith('\n') && !paste.includes('\\n'), s.wf + ' paste file ' + path.basename(s.paste) + ' = the hotfix node jsCode, exact bytes (plain JS, real newlines, no trailing newline)');
  check(pasteBefore === bc && !pasteBefore.endsWith('\n'), s.wf + ' paste file ' + path.basename(s.pasteBefore) + ' = the BEFORE (live) node jsCode, exact bytes (rollback)');
  const stepC = JSON.parse(fs.readFileSync(s.stepC, 'utf8')).filter((o) => o.type === 'updateNodeParameters' && o.nodeName === NODE);
  check(stepC.length === 1 && stepC[0].replace === true && same(Object.keys(stepC[0].parameters), ['jsCode']) && stepC[0].parameters.jsCode === mc && caps.pruningTailOf(stepC[0].parameters.jsCode) === caps.pruningTailOf(hc), s.wf + ': ../ops/' + path.basename(s.stepC) + ' carries the ' + NODE + ' node of the main source (Step C after the hot-fix: ' + (s.wf === 'wf2' ? 'the identical node, an idempotent replace' : 'the same pruning tail plus the region branch head') + ')');
  check(readme.includes(s.id) && readme.includes(path.basename(s.ops)) && readme.includes(path.basename(s.paste)) && readme.includes(path.basename(s.pasteBefore)) && readme.includes(path.basename(s.hotfix)), 'README names ' + s.id + ', ' + path.basename(s.ops) + ', ' + path.basename(s.paste) + ', ' + path.basename(s.pasteBefore) + ', ' + path.basename(s.hotfix));
  check(rulesOk(hc), s.wf + ' hotfix jsCode: at most 20 lines (' + hc.split('\n').length + '), quote-free top-level comments, colon-free thrown messages, no backslash');
}
check(caps.pruningTailOf(codes.wf2.main) === caps.pruningTailOf(codes.wf3.main) && caps.pruningTailOf(codes.wf2.hot) === caps.pruningTailOf(codes.wf3.hot) && caps.pruningTailOf(codes.wf2.main) === caps.pruningTailOf(codes.wf3.hot), 'the pruning tail is byte-identical across WF-2 main, WF-3 main, WF-2 hotfix and WF-3 hotfix');
check(/timeout: 5000/.test(caps.pruningTailOf(codes.wf2.main)) && /catch \{/.test(caps.pruningTailOf(codes.wf2.main)) && /typeof fit === 'string'/.test(caps.pruningTailOf(codes.wf2.main)), 'the pruning tail: descriptor GET timeout 5000, optional catch binding, the fit shape check guarded by typeof (inert where no head defines fit)');

// 2. the hotfix codes under the live graph shapes (run as the async n8n function; {} = no helper = static table, ctxFixtures = live descriptors)
const mock$ = (data) => (name) => ({ get isExecuted() { return name in data; }, first: () => { if (!(name in data)) throw new Error('unmocked node ' + name); return { json: data[name][0] }; }, last: () => ({ json: data[name][data[name].length - 1] }), all: () => data[name].map((json) => ({ json })) });
const run = (code, data, item, ctx) => new caps.AsyncFunction('$', '$input', '$json', '$execution', code).call(ctx, mock$(data), { first: () => ({ json: item }), all: () => [{ json: item }] }, item, { resumeUrl: 'u' }).then((o) => o.json);
(async () => {
  const code2 = fs.readFileSync(SETS[0].paste, 'utf8'), code3 = fs.readFileSync(SETS[1].paste, 'utf8'), main3 = codes.wf3.main;
  const SUN_KEYS = ['model', 'prompt', 'n', 'aspect_ratio', 'background', 'input_references'], TEXT_KEYS = ['model', 'prompt', 'n', 'aspect_ratio', 'input_references'];
  const models = { image: 'openai/gpt-image-2.5-sunburst', edit: 'google/gemini-2.5-flash-image', region: 'openai/gpt-image-2.5-sunburst' };
  // the user's failing generation cf89b565 (card 2e99c36b, placement back): Sunburst, aspect_ratio 4:5, resolution 2K, output_format png, 3 input references
  const urls3 = ['https://sb/sign/brief.png?t=1', 'https://sb/sign/style.png?t=2', 'https://sb/sign/art.png?t=3'];
  const pe45 = { aspect_ratio: '4:5', resolution: '2K', openrouter_models: models };
  const gen45 = { body: { model: 'gpt-image-2-5-sunburst-image-to-image', input: { prompt: 'P', input_urls: urls3, aspect_ratio: '4:5', resolution: '2K', background: 'opaque' } } };
  for (const [label, ctx, src] of [['static table', {}, 'static'], ['live Sunburst fixture', caps.ctxFixtures(), 'live']]) {
    const o = await run(code2, { 'Prompt Engine': [pe45], 'Build Create Task': [gen45] }, gen45, ctx);
    check(same(Object.keys(o.body), SUN_KEYS) && o.body.aspect_ratio === '3:4' && o.body.model === models.image && o.body.n === 1 && o.body.background === 'opaque' && o.body.input_references.length === 3 && same(o.dropped, ['resolution', 'output_format']) && same(o.mapped, ['aspect_ratio 4:5 to 3:4']) && o.caps_source === src, 'wf2 paste code, the 2e99c36b case (Sunburst, 4:5, 2K, png, 3 refs) with the ' + label + ': body keys exactly ' + SUN_KEYS.join(',') + ', aspect_ratio 3:4, dropped [resolution, output_format], mapped [aspect_ratio 4:5 to 3:4], caps_source ' + src);
  }
  const pe = { aspect_ratio: '1:1', resolution: '2K', openrouter_models: models };
  const gen = { body: { model: 'gpt-image-2-5-sunburst-image-to-image', input: { prompt: 'P', input_urls: ['u1', 'u2'], aspect_ratio: '1:1', resolution: '2K', background: 'opaque' } } };
  const o2 = await run(code2, { 'Prompt Engine': [pe], 'Build Create Task': [gen] }, gen, {}), l2 = await run(code2, { 'Prompt Engine': [pe], 'Build Create Task': [gen] }, gen, caps.ctxFixtures());
  check(same(Object.keys(o2.body), SUN_KEYS) && o2.body.aspect_ratio === '1:1' && same(o2.dropped, ['resolution', 'output_format']) && same(o2.mapped, []) && o2.caps_source === 'static' && same(l2.body, o2.body) && same(l2.mapped, []) && l2.caps_source === 'live', 'wf2 paste code, a 1:1 Sunburst generate: body ' + SUN_KEYS.join(',') + ', dropped [resolution, output_format], mapped [] - static and live');
  // WF-3 live graph shape: Prompt Engine (textPe, no region, no openrouter_models), Build Edit Task = the live Nano Banana body with image_urls
  const textPe = { kind: 'edit_text', aspect_ratio: '1:1', resolution: '2K', region: null };
  const edit = { body: { model: 'google/nano-banana-edit', input: { prompt: 'E', image_urls: ['u1'], output_format: 'png' } } };
  const o3 = await run(code3, { 'Prompt Engine': [textPe], 'Build Edit Task': [edit] }, edit, {}), l3 = await run(code3, { 'Prompt Engine': [textPe], 'Build Edit Task': [edit] }, edit, caps.ctxFixtures());
  check(same(Object.keys(o3.body), TEXT_KEYS) && same(o3.dropped, ['resolution', 'output_format']) && same(o3.mapped, []) && o3.caps_source === 'static' && o3.body.model === models.edit && o3.body.input_references.length === 1 && same(l3.body, o3.body) && l3.caps_source === 'live', 'wf3 paste code (live graph shape: Build Edit Task image_urls, no region): gemini-2.5-flash-image body ' + TEXT_KEYS.join(',') + ', dropped [resolution, output_format], mapped [] - static and live');
  const o345 = await run(code3, { 'Prompt Engine': [{ ...textPe, aspect_ratio: '4:5' }], 'Build Edit Task': [edit] }, edit, caps.ctxFixtures()), s345 = await run(code3, { 'Prompt Engine': [{ ...textPe, aspect_ratio: '4:5' }], 'Build Edit Task': [edit] }, edit, {});
  check(o345.body.aspect_ratio === '4:5' && same(o345.mapped, []) && s345.body.aspect_ratio === '4:5' && same(s345.mapped, []), 'wf3 paste code, edit_text of a 4:5 parent on gemini-2.5-flash-image: 4:5 is listed, kept, mapped [] - live and static');
  // prompt-engine v8.1 already deployed (pe.region PRESENT) while the live graph still has no region lane: the hotfix must take the edit path
  const region = { rect: { x: 10, y: 10, w: 20, h: 20 }, prompt: 'make the sunglasses red', aspect_ratio: '1:1', quality: 'high', mask_attached: true, openrouter_model: models.region };
  const peReg = { ...textPe, kind: 'edit_region', region, openrouter_models: models };
  const editMask = { body: { model: 'google/nano-banana-edit', input: { prompt: 'E with mask', image_urls: ['u1', 'u-mask'], output_format: 'png' } } };
  const hotReg = await run(code3, { 'Prompt Engine': [peReg], 'Build Edit Task': [editMask] }, editMask, caps.ctxFixtures()), mainReg = await run(main3, { 'Prompt Engine': [peReg], 'Build Edit Task': [editMask] }, editMask, caps.ctxFixtures());
  check(same(Object.keys(hotReg.body), TEXT_KEYS) && hotReg.body.model === models.edit && hotReg.body.prompt === 'E with mask' && !('quality' in hotReg.body) && hotReg.body.input_references.length === 2 && same(hotReg.dropped, ['resolution', 'output_format']), 'wf3 paste code with pe.region PRESENT (BEFORE fixtures): still the edit path - gemini-2.5-flash-image, the Build Edit Task prompt, no quality - the hot-fix cannot change behaviour on the live graph');
  check(mainReg.body.model === models.region && mainReg.body.quality === 'high' && mainReg.body.prompt === region.prompt, 'the main WF-3 node under the same inputs takes the region branch (Sunburst, quality high) - that is what Step C adds, not the hot-fix');
  // a really 4:5 parent (Kie- or Gemini-made, mask_rect 1638x2048) with pe.region present: the shared tail checks the shape against fit only when a head defined it - the BEFORE head never does, the main head does
  const peKie = { ...peReg, aspect_ratio: '4:5', region: { ...region, aspect_ratio: '4:5', rect: { ...region.rect, width: 1638, height: 2048 } } };
  const hotKie = await run(code3, { 'Prompt Engine': [peKie], 'Build Edit Task': [editMask] }, editMask, caps.ctxFixtures());
  const mainKie = await run(main3, { 'Prompt Engine': [peKie], 'Build Edit Task': [editMask] }, editMask, caps.ctxFixtures()).then(() => null, (e) => e.message);
  check(hotKie.body.model === models.edit && hotKie.body.aspect_ratio === '4:5' && same(hotKie.mapped, []) && same(hotKie.dropped, ['resolution', 'output_format']), 'wf3 paste code with a really 4:5 parent (mask_rect 1638x2048) and pe.region PRESENT: no fit in the BEFORE head, so the shape check is inert - edit path, gemini-2.5-flash-image keeps 4:5, nothing thrown');
  check(mainKie === 'Fix an area cannot run on this 1638x2048 px design - the image model lists no aspect ratio within 1 percent of that shape (nearest 3 by 4) and the composite step never stretches a regeneration, so none was started' && !/:/.test(mainKie || ':'), 'the main WF-3 node under the same inputs throws the colon-free shape message before the paid call (GPT Image renders no ratio within 1 % of 4:5; region-composite would answer size_mismatch 422) - Step C behaviour, never the hot-fix');
  const inputUrls = { body: { model: 'x', input: { prompt: 'E', input_urls: ['u1'] } } };
  const hotIn = await run(code3, { 'Prompt Engine': [textPe], 'Build Edit Task': [inputUrls] }, inputUrls, {});
  check(!('input_references' in hotIn.body) && same(Object.keys(hotIn.body), ['model', 'prompt', 'n', 'aspect_ratio']), 'wf3 paste code reads image_urls only (the BEFORE head): a Kie-shaped input_urls item sends no input_references, exactly as the live node does');
  let err = null;
  try { await run(code3, { 'Prompt Engine': [textPe], 'Build Edit Task': [{ body: { input: {} } }] }, { body: { input: {} } }, {}); } catch (e) { err = e; }
  check(err && err.message === 'no edit request to send to OpenRouter', 'wf3 paste code without a prompt throws the colon-free BEFORE message no edit request to send to OpenRouter');
  console.log(failures ? `\n${failures} check(s) failed` : '\nall checks passed');
  process.exit(failures ? 1 : 0);
})().catch((e) => { console.log('FAIL test threw ' + ((e && e.stack) || e)); process.exit(1); });
